import{_ as t,h as e,o as a,a9 as o}from"./chunks/framework.DrXHgEgV.js";const b=JSON.parse('{"title":"前端项目 PV/UV 统计工具推荐","description":"","frontmatter":{},"headers":[],"relativePath":"daily-notes/issue-9.md","filePath":"daily-notes/issue-9.md","lastUpdated":1761189984000}'),r={name:"daily-notes/issue-9.md"},i=o('<h1 id="前端项目-pv-uv-统计工具推荐" tabindex="-1">前端项目 PV/UV 统计工具推荐 <a class="header-anchor" href="#前端项目-pv-uv-统计工具推荐" aria-label="Permalink to &quot;前端项目 PV/UV 统计工具推荐&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">原文地址</p><p><a href="https://github.com/wangkuowink/daily-notes/issues/9" target="_blank" rel="noreferrer">前端项目 PV/UV 统计工具推荐 | GitHub</a></p></div><p>在前端开发中，统计页面访问量（PV）和独立访客（UV）是一项常见需求。本文针对 Vue3 + TypeScript 项目，分享一些开源、可自托管的统计工具，并分析各自的特点，帮助你选择合适的方案。</p><hr><h2 id="_1-背景说明" tabindex="-1">1. 背景说明 <a class="header-anchor" href="#_1-背景说明" aria-label="Permalink to &quot;1. 背景说明&quot;">​</a></h2><p>在前端项目中统计 PV 和 UV 时，需要考虑以下几个方面：</p><ul><li><strong>开源免费</strong>：工具免费且源代码可查看和修改。</li><li><strong>自托管</strong>：希望掌握数据，不依赖第三方服务。</li><li><strong>前端集成</strong>：适合 Vue3 + TypeScript 项目，集成简单。</li></ul><p>基于这些需求，我们筛选了几款开源统计工具，并对比了 Google Analytics（GA）。</p><hr><h2 id="_2-开源-自托管工具推荐" tabindex="-1">2. 开源 / 自托管工具推荐 <a class="header-anchor" href="#_2-开源-自托管工具推荐" aria-label="Permalink to &quot;2. 开源 / 自托管工具推荐&quot;">​</a></h2><table><thead><tr><th>工具</th><th>优点</th><th>注意事项</th></tr></thead><tbody><tr><td><strong>Umami</strong></td><td>- MIT 协议，自托管，支持 Docker 部署 <br>- 界面简洁，专注 PV/UV 和事件统计 <br>- 隐私友好，不依赖复杂 Cookie <br>- SPA/Vue3 集成方便</td><td>- 功能基础，不支持热图、会话回放等高级分析 <br>- 自托管需自己维护服务器稳定性和安全性</td></tr><tr><td><strong>Plausible Analytics</strong></td><td>- AGPLv3，自托管 <br>- 轻量、隐私优先 <br>- 小型项目足够 PV/UV 和来源统计</td><td>- 功能简单，事件追踪或跨端统计有限</td></tr><tr><td><strong>Matomo</strong></td><td>- 功能全面，包括 PV/UV、路径分析、会话记录、热图 <br>- 数据掌控、插件扩展性强</td><td>- 部署复杂，资源消耗高 <br>- 小型项目可能过于重量级</td></tr><tr><td><strong>Open Web Analytics (OWA)</strong></td><td>- 开源，自托管，支持基本 PV/UV</td><td>- 社区活跃度低，现代 SPA 集成体验较差</td></tr></tbody></table><p><strong>推荐总结</strong></p><ul><li>中小型 Vue3 SPA 项目 → Umami，轻量、易部署</li><li>隐私优先、流量不大 → Plausible</li><li>复杂业务、需要深入分析 → Matomo</li></ul><hr><h2 id="_3-google-analytics-ga-分析" tabindex="-1">3. Google Analytics（GA）分析 <a class="header-anchor" href="#_3-google-analytics-ga-分析" aria-label="Permalink to &quot;3. Google Analytics（GA）分析&quot;">​</a></h2><p>GA 是成熟的统计工具，但不完全符合开源自托管的条件。</p><table><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>免费，可处理大流量</td><td>不自托管，数据在 Google 云端，不可完全掌控</td></tr><tr><td>功能丰富，支持事件追踪和用户行为分析</td><td>隐私法规约束较多（GDPR、CCPA）</td></tr><tr><td>插件和社区丰富，集成方便</td><td>SPA 需要额外处理路由统计</td></tr><tr><td>易于 Vue3 集成</td><td>无法直接访问原始数据库，灵活性有限</td></tr></tbody></table><p>总结：如果不在意自托管，GA 是成熟稳定的选择；若需要控制数据，自托管工具更合适。</p><hr><h2 id="_4-uv-统计原理-以-umami-为例" tabindex="-1">4. UV 统计原理（以 Umami 为例） <a class="header-anchor" href="#_4-uv-统计原理-以-umami-为例" aria-label="Permalink to &quot;4. UV 统计原理（以 Umami 为例）&quot;">​</a></h2><ul><li><strong>PV（页面访问量）</strong>：每次页面加载或路由切换都会计数。</li><li><strong>UV（独立访客）</strong>：通过浏览器 Local Storage 或 Cookie 生成 visitor ID 来识别不同访客。</li><li><strong>SPA 页面</strong>：前端需调用 <code>trackView(path)</code>，Umami 会根据 visitor ID 判断是否为新访客。</li><li><strong>跨设备统计</strong>：可以使用登录系统中的用户 ID，在前端调用 <code>trackEvent</code> 或 <code>trackView</code> 时传入 <code>user_id</code>。</li><li><strong>注意</strong>：清除 Local Storage/Cookie 或使用隐身模式可能会导致 UV 重复统计。</li></ul><hr><h2 id="_5-前端-vue3-集成建议" tabindex="-1">5. 前端 Vue3 集成建议 <a class="header-anchor" href="#_5-前端-vue3-集成建议" aria-label="Permalink to &quot;5. 前端 Vue3 集成建议&quot;">​</a></h2><p>可以参考我之前的博客，详细介绍了 Vue3 + Umami 的集成方法：[<a href="https://wangkuowink.github.io/wk-notes/daily-notes/issue-8" target="_blank" rel="noreferrer">点击查看</a>](<a href="https://wangkuowink.github.io/wk-notes/daily-notes/issue-8" target="_blank" rel="noreferrer">https://wangkuowink.github.io/wk-notes/daily-notes/issue-8</a>)</p><p>核心步骤：</p><ol><li>在 <code>public/index.html</code> 引入 Umami 脚本。</li><li>在 <code>router.ts</code> 中使用 <code>afterEach</code> 钩子统计 PV。</li><li>在按钮或事件处调用 <code>trackEvent</code> 上报事件。</li></ol><p>适用于 Vue3 + TypeScript SPA 项目，多端统计或登录用户可带自定义 <code>user_id</code>。</p><hr><h2 id="_6-总结与选择指南" tabindex="-1">6. 总结与选择指南 <a class="header-anchor" href="#_6-总结与选择指南" aria-label="Permalink to &quot;6. 总结与选择指南&quot;">​</a></h2><ul><li><strong>轻量、易用、自托管</strong> → Umami</li><li><strong>隐私优先、简洁统计</strong> → Plausible</li><li><strong>复杂分析、高级功能</strong> → Matomo</li><li><strong>快速成熟、无需自托管</strong> → GA</li></ul><p>从前端角度来看，Umami 是最适合 Vue3 SPA 项目展示 PV/UV 的开源方案，同时保留可扩展性和自托管优势。</p>',31),l=[i];function s(d,n,c,h,u,g){return a(),e("div",null,l)}const m=t(r,[["render",s]]);export{b as __pageData,m as default};
